import binascii, json, sys, unicodedata
rows = []
for name in ['a2b_base64', 'unhexlify', 'a2b_hex', 'a2b_qp', 'a2b_uu']:
    try:
        getattr(binascii, name)(None)
    except Exception as error:
        rows.append({'name': name, 'type': type(error).__name__, 'args': error.args})
print(json.dumps({'version': sys.version, 'unicode': unicodedata.unidata_version,
                  'platform': sys.platform, 'byteorder': sys.byteorder, 'results': rows}))

