import fs from 'node:fs';
import assert from 'node:assert/strict';
import {createRuntimeBase64Functions} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-base64-functions.ts';
import {createRuntimeHexadecimalFunctions} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-hexadecimal-functions.ts';
import {createRuntimeQuotedPrintableFunctions} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-quoted-printable-functions.ts';
import {createRuntimeUuFunctions} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-uu-functions.ts';
import {ExecutionBudget,ExecutionLimitError} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/execution-budget.ts';
import {PythonRuntimeError} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/error.ts';
import {RuntimeValues} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-values.ts';
import {RuntimeTypeRegistry} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-type-registry.ts';
import {RuntimeExceptionExecution} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/runtime-exception-execution.ts';
import {OrderedKeyMap} from '/Users/kjopek/Workspace/poe-code-3/packages/safe-python/src/runtime/ordered-key-map.ts';
const decoders=[['a2b_base64',createRuntimeBase64Functions],['unhexlify',createRuntimeHexadecimalFunctions],['a2b_hex',createRuntimeHexadecimalFunctions],['a2b_qp',createRuntimeQuotedPrintableFunctions],['a2b_uu',createRuntimeUuFunctions]] as const;

const results=[];let reads=0,writes=0,fsyncs=0;
for(const [name,create] of decoders)for(const outcome of ['return','ordinary','fatal','cancel']){
 const fd=fs.openSync('/tmp/binary-missing-buffer-service-output.txt','w+');
 try{
  const controller=new AbortController();
  const meter=new ExecutionBudget({maxSteps:100000,maxAllocatedBytes:1000000,signal:controller.signal});
  const values=new RuntimeValues(meter),keys={hash:()=>0n,equal:(a,b)=>a===b};
  const types=new RuntimeTypeRegistry(values,keys,meter),exceptions=new RuntimeExceptionExecution(types,values,meter);
  const failure=exceptions.prepare(new PythonRuntimeError('ValueError','diagnostic failed')),fatal=new ExecutionLimitError('steps');
  const fn=new Map(create(values,meter)).get(name)!,keywords=values.dictionary(new OrderedKeyMap(keys,meter));
  const write=(event:string)=>{const bytes=Buffer.from(event+'\n');let offset=0;while(offset<bytes.length){const count=fs.writeSync(fd,bytes,offset,bytes.length-offset);assert.ok(count>0);offset+=count;writes++;}fs.fsyncSync(fd);fsyncs++;};
  const context={call(){throw Error('unexpected call');},isException(error,type){write('classify');return exceptions.matches(error,type);},buffers:{acquireSimple(){write('acquire');return undefined;},typeName(value){write('name');if(outcome==='ordinary')throw failure;if(outcome==='fatal')throw fatal;if(outcome==='cancel')controller.abort();return types.nativeType(value)!.value.name;}}};
  const invoke=()=>fn.value.invoke([values.none],keywords,meter,context);
  let caught;try{invoke();}catch(error){caught=error;}
  if(outcome==='cancel'){assert.ok(caught instanceof ExecutionLimitError);assert.equal(caught.reason,'cancelled');assert.throws(invoke,ExecutionLimitError);}
  else if(outcome==='ordinary')assert.equal(caught,failure);
  else if(outcome==='fatal')assert.equal(caught,fatal);
  else{assert.ok(caught instanceof PythonRuntimeError);assert.equal(caught.name,'TypeError');assert.equal(caught.message,"argument should be bytes, buffer or ASCII string, not 'NoneType'");}
  const data=Buffer.alloc(fs.fstatSync(fd).size);let offset=0;while(offset<data.length){const count=fs.readSync(fd,data,offset,data.length-offset,offset);assert.ok(count>0);offset+=count;reads++;}
  assert.equal(data.toString(),'acquire\nname\n');results.push({name,outcome,output:data.toString(),matched:true});
 }finally{fs.closeSync(fd);}
}
fs.writeFileSync('/tmp/binary-missing-buffer-services.json',JSON.stringify({results,reads,writes,fsyncs},null,2)+'\n');
console.log(JSON.stringify({passed:results.length,reads,writes,fsyncs}));
